"""The emergent space of n Bell pairs is exactly n microscopic wormholes.

Take 2n cells paired off, with pair i joined by a wall of area w_i and no
other walls.  The throat capacity inside a pair is exactly w_i and across pairs
it is 0, so the emergent distance is exp(-w_i) inside a pair and the maximal
value 1 across pairs.  Consequently, at any resolution r in the window
[max_i exp(-w_i), 1) the clusters of the emergent ultrametric are precisely the
Bell pairs: a shattered spacetime whose only connectivity is entanglement.
"""

from __future__ import annotations

import math
from typing import Dict, Iterable, List, Sequence, Tuple

Matrix = List[List[float]]
Region = int


def make_geometry(n: int, edges: Dict[Tuple[int, int], float]) -> Matrix:
    """Symmetric nonnegative area matrix from a dictionary of wall areas."""
    w: Matrix = [[0.0] * n for _ in range(n)]
    for (x, y), val in edges.items():
        if val < 0.0:
            raise ValueError("areas must be nonnegative")
        w[x][y] = float(val)
        w[y][x] = float(val)
    return w


def in_region(f: Region, x: int) -> bool:
    """Is cell x inside the region f?"""
    return (f >> x) & 1 == 1


def region_of(cells: Iterable[int]) -> Region:
    """Bitmask of a collection of cells."""
    f = 0
    for x in cells:
        f |= 1 << x
    return f


def area(w: Matrix, f: Region) -> float:
    """Area of the surface bounding the region f."""
    n = len(w)
    return sum(w[x][y]
               for x in range(n) if in_region(f, x)
               for y in range(n) if not in_region(f, y))


def entropy(w: Matrix, boundary: Region, a: Region) -> float:
    """Ryu-Takayanagi entropy: min area over regions agreeing with A on the boundary."""
    n = len(w)
    return min(area(w, f) for f in range(1 << n)
               if (f & boundary) == (a & boundary))


def mutual_information(w: Matrix, boundary: Region, a: Region, b: Region) -> float:
    """I(A:B) = S(A) + S(B) - S(A u B)."""
    return (entropy(w, boundary, a) + entropy(w, boundary, b)
            - entropy(w, boundary, a | b))


def throat(w: Matrix, a: Region, b: Region) -> float:
    """Throat capacity: min area over regions containing A and missing B."""
    n = len(w)
    vals = [area(w, f) for f in range(1 << n) if (f & a) == a and (f & b) == 0]
    return min(vals) if vals else 0.0


def cap(w: Matrix, u: int, v: int) -> float:
    """Bridge capacity between two single cells."""
    return throat(w, 1 << u, 1 << v)


def bridge_distance(w: Matrix, u: int, v: int) -> float:
    """Emergent distance d(u,v) = exp(-cap(u,v))."""
    return 0.0 if u == v else math.exp(-cap(w, u, v))




def bell_geometry(weights: Sequence[float]) -> Matrix:
    """2n cells, pair i joined by a wall of area weights[i]."""
    n = 2 * len(weights)
    return make_geometry(n, {(2 * i, 2 * i + 1): wi for i, wi in enumerate(weights)})


def clusters_at_scale(w: Matrix, r: float) -> List[List[int]]:
    """Clusters of the emergent ultrametric at scale r (an honest equivalence relation)."""
    n = len(w)
    parent = list(range(n))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u in range(n):
        for v in range(u + 1, n):
            if bridge_distance(w, u, v) <= r + 1e-12:
                parent[find(u)] = find(v)
    groups: Dict[int, List[int]] = {}
    for x in range(n):
        groups.setdefault(find(x), []).append(x)
    return sorted((sorted(g) for g in groups.values()), key=lambda g: g[0])


def demo() -> None:
    weights = [2.0, 1.0, 0.5]
    w = bell_geometry(weights)
    n = len(w)
    bdy = (1 << n) - 1
    print("pair   w_i     I/2       E    min(S,S)   d inside   d across")
    for i, wi in enumerate(weights):
        u, v = 2 * i, 2 * i + 1
        info = mutual_information(w, bdy, 1 << u, 1 << v)
        thr = cap(w, u, v)
        m = min(entropy(w, bdy, 1 << u), entropy(w, bdy, 1 << v))
        across = bridge_distance(w, u, (u + 2) % n)
        print(f"  {i}  {wi:6.2f}  {info / 2:6.2f}  {thr:6.2f}  {m:9.2f}"
              f"  {bridge_distance(w, u, v):9.4f}  {across:9.4f}")
    print()
    lo = max(math.exp(-wi) for wi in weights)
    for r in (0.2 * lo, lo, 0.5 * (lo + 1.0), 0.999, 1.0):
        print(f"  scale r = {r:6.4f}   clusters = {clusters_at_scale(w, r)}")
    print()
    print(f"  Inside the window [{lo:.4f}, 1) the clusters are exactly the Bell pairs.")
    print("  Below it the space shatters into points; at r = 1 everything merges.")


if __name__ == "__main__":
    demo()

