"""Throat capacity of an Einstein-Rosen bridge (unconstrained minimum cut).

Computes E(A,B), the smallest area of a surface containing A and missing B.
Two implementations are given: an exact exhaustive search over all 2^n regions
(which also returns the minimising region, useful for small studies), and the
polynomial Edmonds-Karp maximum flow, whose value equals the min cut and whose
agreement with the exhaustive answer is the computational face of duality.
"""

from __future__ import annotations

import math
from typing import Dict, Iterable, List, Sequence, Tuple

Matrix = List[List[float]]
Region = int


def make_geometry(n: int, edges: Dict[Tuple[int, int], float]) -> Matrix:
    """Symmetric nonnegative area matrix from a dictionary of wall areas."""
    w: Matrix = [[0.0] * n for _ in range(n)]
    for (x, y), val in edges.items():
        if val < 0.0:
            raise ValueError("areas must be nonnegative")
        w[x][y] = float(val)
        w[y][x] = float(val)
    return w


def in_region(f: Region, x: int) -> bool:
    """Is cell x inside the region f?"""
    return (f >> x) & 1 == 1


def region_of(cells: Iterable[int]) -> Region:
    """Bitmask of a collection of cells."""
    f = 0
    for x in cells:
        f |= 1 << x
    return f


def area(w: Matrix, f: Region) -> float:
    """Area of the surface bounding the region f."""
    n = len(w)
    return sum(w[x][y]
               for x in range(n) if in_region(f, x)
               for y in range(n) if not in_region(f, y))


def entropy(w: Matrix, boundary: Region, a: Region) -> float:
    """Ryu-Takayanagi entropy: min area over regions agreeing with A on the boundary."""
    n = len(w)
    return min(area(w, f) for f in range(1 << n)
               if (f & boundary) == (a & boundary))


def mutual_information(w: Matrix, boundary: Region, a: Region, b: Region) -> float:
    """I(A:B) = S(A) + S(B) - S(A u B)."""
    return (entropy(w, boundary, a) + entropy(w, boundary, b)
            - entropy(w, boundary, a | b))


def throat(w: Matrix, a: Region, b: Region) -> float:
    """Throat capacity: min area over regions containing A and missing B."""
    n = len(w)
    vals = [area(w, f) for f in range(1 << n) if (f & a) == a and (f & b) == 0]
    return min(vals) if vals else 0.0


def cap(w: Matrix, u: int, v: int) -> float:
    """Bridge capacity between two single cells."""
    return throat(w, 1 << u, 1 << v)


def bridge_distance(w: Matrix, u: int, v: int) -> float:
    """Emergent distance d(u,v) = exp(-cap(u,v))."""
    return 0.0 if u == v else math.exp(-cap(w, u, v))




def throat_with_witness(w: Matrix, a: Region, b: Region) -> Tuple[float, Region]:
    """Exhaustive throat capacity, returning the value and a minimising region."""
    n = len(w)
    best, arg = math.inf, 0
    for f in range(1 << n):
        if (f & a) != a or (f & b) != 0:
            continue
        val = area(w, f)
        if val < best:
            best, arg = val, f
    return (0.0, 0) if best is math.inf else (best, arg)


def max_flow(w: Matrix, s: int, t: int) -> Tuple[float, Matrix]:
    """Edmonds-Karp maximum flow; the resulting flow is a saturating bit-thread field."""
    n = len(w)
    residual: Matrix = [row[:] for row in w]
    flow: Matrix = [[0.0] * n for _ in range(n)]
    total = 0.0
    while True:
        parent = [-1] * n
        parent[s] = s
        queue = [s]
        while queue and parent[t] == -1:
            x = queue.pop(0)
            for y in range(n):
                if parent[y] == -1 and residual[x][y] > 1e-12:
                    parent[y] = x
                    queue.append(y)
        if parent[t] == -1:
            return total, flow
        bottleneck = math.inf
        y = t
        while y != s:
            bottleneck = min(bottleneck, residual[parent[y]][y])
            y = parent[y]
        y = t
        while y != s:
            x = parent[y]
            residual[x][y] -= bottleneck
            residual[y][x] += bottleneck
            flow[x][y] += bottleneck
            flow[y][x] -= bottleneck
            y = x
        total += bottleneck


def demo() -> None:
    w = make_geometry(5, {(0, 1): 3.0, (1, 2): 1.0, (2, 3): 4.0, (3, 4): 2.0, (1, 4): 0.5})
    for u, v in [(0, 4), (0, 2), (1, 3), (2, 4)]:
        exact, witness = throat_with_witness(w, 1 << u, 1 << v)
        flowval, _ = max_flow(w, u, v)
        side = [x for x in range(5) if in_region(witness, x)]
        print(f"  E({u},{v}) = {exact:5.2f}   max-flow = {flowval:5.2f}"
              f"   minimising region = {side}"
              f"   d = {math.exp(-exact):.4f}")
    print("\n  The exhaustive min cut and the maximum flow agree in every case:")
    print("  weak duality is a theorem, and here the bound is attained.")


if __name__ == "__main__":
    demo()

