  for each pair (u,v) do cap[u][v] <- ThroatCapacity(w, {u}, {v})
  for each pair (u,v) do d[u][v] <- (u = v) ? 0 : exp(-cap[u][v])

  // certification
  for all u, v, z  do assert d[u][z] <= max(d[u][v], d[v][z])           // ultrametric
  for all x,y,z,t  do assert d[x][y] + d[z][t]
                        <= max(d[x][z] + d[y][t], d[x][t] + d[y][z])    // delta = 0

  // the hierarchy of clusters
  scales <- sorted distinct values of d
  hierarchy <- empty list
  for r in scales do
      union-find over cells, joining u ~ v whenever d[u][v] <= r
      partition <- the resulting classes
      if partition differs from the previous one then append (r, partition)
  return (cap, d, hierarchy)

