"""Construction of the emergent ultrametric and its hierarchy of entanglement clusters.

Builds the capacity table cap(u,v) = E({u},{v}), converts it into the emergent
distance d = exp(-cap), verifies the strong triangle inequality and Gromov's
four-point condition with delta = 0, and extracts the laminar family of clusters
at every scale.  Because the distance is an ultrametric, 'within r of each other'
is a genuine equivalence relation at every r, so the clusters are exact and nest
perfectly -- the hierarchy is the dendrogram of a weighted tree.
"""

from __future__ import annotations

import math
from typing import Dict, Iterable, List, Sequence, Tuple

Matrix = List[List[float]]
Region = int


def make_geometry(n: int, edges: Dict[Tuple[int, int], float]) -> Matrix:
    """Symmetric nonnegative area matrix from a dictionary of wall areas."""
    w: Matrix = [[0.0] * n for _ in range(n)]
