    """I(A:B) = S(A) + S(B) - S(A u B)."""
    return (entropy(w, boundary, a) + entropy(w, boundary, b)
            - entropy(w, boundary, a | b))


def throat(w: Matrix, a: Region, b: Region) -> float:
    """Throat capacity: min area over regions containing A and missing B."""
    n = len(w)
    vals = [area(w, f) for f in range(1 << n) if (f & a) == a and (f & b) == 0]
    return min(vals) if vals else 0.0


def cap(w: Matrix, u: int, v: int) -> float:
    """Bridge capacity between two single cells."""
    return throat(w, 1 << u, 1 << v)


def bridge_distance(w: Matrix, u: int, v: int) -> float:
    """Emergent distance d(u,v) = exp(-cap(u,v))."""
    return 0.0 if u == v else math.exp(-cap(w, u, v))




def capacity_table(w: Matrix) -> Matrix:
    """The full table of bridge capacities."""
    n = len(w)
    return [[0.0 if u == v else cap(w, u, v) for v in range(n)] for u in range(n)]


def distance_table(w: Matrix) -> Matrix:
    """The emergent distance matrix."""
    n = len(w)
    return [[bridge_distance(w, u, v) for v in range(n)] for u in range(n)]


def verify_ultrametric(d: Matrix) -> Tuple[float, float]:
    """Worst violations of the strong triangle inequality and the four-point condition."""
    n = len(d)
    ultra = max(d[u][z] - max(d[u][v], d[v][z])
                for u in range(n) for v in range(n) for z in range(n))
    four = max(d[x][y] + d[z][t] - max(d[x][z] + d[y][t], d[x][t] + d[y][z])
               for x in range(n) for y in range(n) for z in range(n) for t in range(n))
    return ultra, four


def cluster_hierarchy(d: Matrix) -> List[Tuple[float, List[List[int]]]]:
    """All distinct cluster partitions, indexed by the scale at which they appear."""
    n = len(d)
    scales = sorted({d[u][v] for u in range(n) for v in range(n)})
    out: List[Tuple[float, List[List[int]]]] = []
    for r in scales:
        parent = list(range(n))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        for u in range(n):
            for v in range(n):
                if d[u][v] <= r + 1e-12:
                    parent[find(u)] = find(v)
        groups: Dict[int, List[int]] = {}
        for x in range(n):
            groups.setdefault(find(x), []).append(x)
        part = sorted((sorted(g) for g in groups.values()), key=lambda g: g[0])
        if not out or out[-1][1] != part:
            out.append((r, part))
    return out


