    w = make_geometry(6, {(0, 1): 3.0, (1, 2): 3.0, (0, 2): 2.0,
                          (2, 3): 0.5, (3, 4): 2.5, (4, 5): 2.5, (3, 5): 1.0})
    d = distance_table(w)
    print("  capacity table cap(u,v):")
    for row in capacity_table(w):
        print("    " + "  ".join(f"{v:5.2f}" for v in row))
    print("  emergent distances d(u,v) = exp(-cap(u,v)):")
    for row in d:
