    print(f"\n  strong triangle inequality: worst violation {ultra:.2e}")
    print(f"  Gromov four-point (delta=0): worst violation {four:.2e}")
    print("\n  the hierarchy of entanglement clusters:")
    for r, part in cluster_hierarchy(d):
        print(f"    r >= {r:6.4f} : " + "  ".join("{" + ",".join(map(str, g)) + "}"
                                                  for g in part))


