        parent = [-1] * n
        parent[s] = s
        queue = [s]
        while queue and parent[t] == -1:
            x = queue.pop(0)
            for y in range(n):
                if parent[y] == -1 and residual[x][y] > 1e-12:
                    parent[y] = x
                    queue.append(y)
        if parent[t] == -1:
            return total, flow
        bottleneck = math.inf
        y = t
        while y != s:
            bottleneck = min(bottleneck, residual[parent[y]][y])
            y = parent[y]
        y = t
        while y != s:
            x = parent[y]
            residual[x][y] -= bottleneck
            residual[y][x] += bottleneck
            flow[x][y] += bottleneck
            flow[y][x] -= bottleneck
            y = x
        total += bottleneck


def audit_threads(w: Matrix, flow: Matrix, s: int, t: int) -> Dict[str, object]:
    """Check the defining properties of a bit-thread configuration and weak duality."""
    n = len(w)
    antisym = all(abs(flow[x][y] + flow[y][x]) < 1e-9 for x in range(n) for y in range(n))
    capacity = all(flow[x][y] <= w[x][y] + 1e-9 for x in range(n) for y in range(n))
    conserved = all(abs(sum(flow[v])) < 1e-9
                    for v in range(n) if v != s and v != t)
    value = sum(flow[s])
    tightest = math.inf
    for f in range(1 << n):
        if not in_region(f, s) or in_region(f, t):
            continue
        a = area(w, f)
        if value > a + 1e-9:
            return {"weak_duality": False}
        tightest = min(tightest, a)
    return {"antisymmetric": antisym, "capacity_respecting": capacity,
            "conserved": conserved, "value": value, "throat": tightest,
            "weak_duality": True, "gap": tightest - value}


def demo() -> None:
    w = make_geometry(6, {(0, 1): 3.0, (0, 2): 2.0, (1, 3): 1.0, (2, 3): 2.5,
                          (1, 2): 1.5, (3, 4): 4.0, (4, 5): 2.0, (3, 5): 1.0})
    for s, t in [(0, 5), (0, 3), (1, 4)]:
        value, flow = max_flow(w, s, t)
        report = audit_threads(w, flow, s, t)
        print(f"  source {s} -> sink {t}")
        print(f"    thread value      {report['value']:.3f}")
        print(f"    throat capacity   {report['throat']:.3f}")
        print(f"    duality gap       {report['gap']:.3e}")
        print(f"    antisymmetric {report['antisymmetric']}, "
              f"capacity-respecting {report['capacity_respecting']}, "
              f"conserved {report['conserved']}")


if __name__ == "__main__":
    demo()

"""Functorial coarse-graining and the renormalisation contraction.

Implements the pushforward of a geometry along a merging map, verifies the
pullback identity that drives the whole renormalisation flow (every coarse surface
equals a fine surface of the same area), and measures the resulting contraction of
the emergent metric.  Also verifies functoriality of successive coarse-grainings
and detects the rigidity case, in which a minimal surface survives the merging and
nothing moves at all.
"""

from __future__ import annotations

import math
from typing import Dict, Iterable, List, Sequence, Tuple

Matrix = List[List[float]]
Region = int


def make_geometry(n: int, edges: Dict[Tuple[int, int], float]) -> Matrix:
    """Symmetric nonnegative area matrix from a dictionary of wall areas."""
    w: Matrix = [[0.0] * n for _ in range(n)]
    for (x, y), val in edges.items():
        if val < 0.0:
            raise ValueError("areas must be nonnegative")
        w[x][y] = float(val)
        w[y][x] = float(val)
    return w


def in_region(f: Region, x: int) -> bool:
    """Is cell x inside the region f?"""
    return (f >> x) & 1 == 1


def region_of(cells: Iterable[int]) -> Region:
    """Bitmask of a collection of cells."""
    f = 0
    for x in cells:
        f |= 1 << x
    return f


def area(w: Matrix, f: Region) -> float:
    """Area of the surface bounding the region f."""
    n = len(w)
    return sum(w[x][y]
               for x in range(n) if in_region(f, x)
               for y in range(n) if not in_region(f, y))


def entropy(w: Matrix, boundary: Region, a: Region) -> float:
    """Ryu-Takayanagi entropy: min area over regions agreeing with A on the boundary."""
    n = len(w)
    return min(area(w, f) for f in range(1 << n)
               if (f & boundary) == (a & boundary))


def mutual_information(w: Matrix, boundary: Region, a: Region, b: Region) -> float:
    """I(A:B) = S(A) + S(B) - S(A u B)."""
    return (entropy(w, boundary, a) + entropy(w, boundary, b)
            - entropy(w, boundary, a | b))


def throat(w: Matrix, a: Region, b: Region) -> float:
    """Throat capacity: min area over regions containing A and missing B."""
    n = len(w)
    vals = [area(w, f) for f in range(1 << n) if (f & a) == a and (f & b) == 0]
    return min(vals) if vals else 0.0


def cap(w: Matrix, u: int, v: int) -> float:
    """Bridge capacity between two single cells."""
    return throat(w, 1 << u, 1 << v)


def bridge_distance(w: Matrix, u: int, v: int) -> float:
    """Emergent distance d(u,v) = exp(-cap(u,v))."""
    return 0.0 if u == v else math.exp(-cap(w, u, v))




def push_geometry(pi: Sequence[int], w: Matrix) -> Matrix:
    """Pushforward: merge cells along pi, summing areas between fibres."""
    m = max(pi) + 1
    out: Matrix = [[0.0] * m for _ in range(m)]
    for x in range(len(w)):
        for y in range(len(w)):
            if pi[x] != pi[y]:
                out[pi[x]][pi[y]] += w[x][y]
    return out


def pullback(pi: Sequence[int], sigma: Region, n: int) -> Region:
    """The fine region obtained by pulling a coarse region back along pi."""
    return region_of([x for x in range(n) if in_region(sigma, pi[x])])


def check_pullback_identity(pi: Sequence[int], w: Matrix) -> float:
    """Worst discrepancy in  area_coarse(sigma) = area_fine(sigma o pi)."""
    wc = push_geometry(pi, w)
    m = len(wc)
    return max(abs(area(wc, s) - area(w, pullback(pi, s, len(w)))) for s in range(1 << m))


def contraction_report(pi: Sequence[int], w: Matrix) -> List[Tuple[int, int, float, float]]:
    """For each pair of fine cells: the fine and coarse emergent distances."""
    wc = push_geometry(pi, w)
    n = len(w)
    return [(u, v, bridge_distance(w, u, v), bridge_distance(wc, pi[u], pi[v]))
            for u in range(n) for v in range(u + 1, n)]


def demo() -> None:
    w = make_geometry(4, {(0, 1): 5.0, (1, 2): 1.0, (2, 3): 5.0})
    pi = [0, 1, 1, 2]
    print(f"  pullback identity, worst discrepancy: {check_pullback_identity(pi, w):.2e}")
    print("   u  v   d fine     d coarse   contracted?")
    for u, v, df, dc in contraction_report(pi, w):
        print(f"   {u}  {v}  {df:8.6f}  {dc:9.6f}   {'yes' if dc <= df + 1e-12 else 'NO'}")
    rho = [0, 0, 1]
    wc = push_geometry(pi, w)
    left = push_geometry(rho, wc)
    right = push_geometry([rho[pi[x]] for x in range(4)], w)
    print(f"\n  functorial: {all(abs(left[a][b] - right[a][b]) < 1e-12 for a in range(2) for b in range(2))}")

    # rigidity: a merging that does not touch the minimal surface changes nothing
    pi2 = [0, 1, 2, 2]
    w2 = push_geometry(pi2, w)
    print(f"  merging cells 2 and 3 (which the min cut does not separate):")
    print(f"    cap fine   = {cap(w, 0, 3):.3f}")
    print(f"    cap coarse = {cap(w2, pi2[0], pi2[3]):.3f}   (unchanged: rigidity)")


if __name__ == "__main__":
    demo()
